	Summary *planSummary      `json:"summary"`
}

func postPlan(t *testing.T, body string) planResult {
	t.Helper()
	rec := httptest.NewRecorder()
	Handler().ServeHTTP(rec, httptest.NewRequest(http.MethodPost, "/v1/plans", strings.NewReader(body)))
